<script setup>
import {ref,computed} from 'vue';
import {themeService} from '../services/theme.service.js';
import {useModalAccessibility} from '../composables/useModalAccessibility.js';
const emit=defineEmits(['close']);
const dialog=ref(null),query=ref(''),filter=ref('all');
const themes=themeService.list();
const lightIds=new Set(['light','mistral','warm','papergrid','popcanvas']);
const appearance=t=>t.appearance || (lightIds.has(t.id)?'light':'dark');
const visible=computed(()=>themes.filter(t=>(filter.value==='all'||appearance(t)===filter.value)&&`${t.name} ${t.blurb}`.toLowerCase().includes(query.value.toLowerCase())));
useModalAccessibility(dialog,{onClose:()=>emit('close')});
</script>
<template>
 <Teleport to="body"><div class="theme-gallery-backdrop" @click.self="$emit('close')"><section ref="dialog" class="theme-gallery" role="dialog" aria-modal="true" :aria-label="$ui('Themes')" tabindex="-1">
 <header><div><span class="bz-eyebrow">{{ $ui('Appearance') }}</span><h2>{{ $ui('Make it yours') }}</h2></div><button class="bz-iconbtn" :aria-label="$ui('Close')" @click="$emit('close')"><span class="material-symbols-outlined" aria-hidden="true">close</span></button></header>
 <div class="theme-gallery-tools"><input v-model="query" type="search" :placeholder="$ui('Search themes')" :aria-label="$ui('Search themes')"/><select v-model="filter" :aria-label="$ui('Appearance')"><option value="all">{{ $ui('All themes') }}</option><option value="dark">{{ $ui('Dark') }}</option><option value="light">{{ $ui('Light') }}</option></select></div>
 <div class="theme-gallery-grid"><button v-for="theme in visible" :key="theme.id" class="theme-preview" :aria-pressed="themeService.state.current===theme.id" @click="themeService.set(theme.id)"><span class="theme-preview-art" :style="{'--sample-bg':theme.swatch[0],'--sample-accent':theme.swatch[1],'--sample-secondary':theme.swatch[2]}"><i/><span class="theme-preview-lines"><b/><b/><b/></span><span class="theme-preview-orb"/></span><span class="theme-preview-name">{{ theme.name }}<span v-if="themeService.state.current===theme.id" class="material-symbols-outlined" aria-hidden="true">check_circle</span></span><small>{{ $ui(appearance(theme)==='light'?'Light':'Dark') }}</small></button></div>
 <p v-if="!visible.length">{{ $ui('No matching themes') }}</p>
 <footer><span>{{ visible.length }} / {{ themes.length }}</span><button class="bz-btn bz-btn--primary" @click="$emit('close')">{{ $ui('Done') }}</button></footer>
 </section></div></Teleport>
</template>
<style scoped>
.theme-gallery-backdrop{position:fixed;inset:0;z-index:2200;background:var(--bz-overlay);display:grid;place-items:center;padding:24px}.theme-gallery{width:min(960px,100%);max-height:90dvh;overflow:auto;background:var(--bz-canvas);color:var(--bz-fg);padding:28px;border:1px solid var(--bz-border-strong);border-radius:20px}.theme-gallery header,.theme-gallery footer{display:flex;justify-content:space-between;align-items:center;gap:16px}.theme-gallery h2{font:900 italic 28px/1.2 var(--bz-font-metric);margin:6px 0 0}.theme-gallery-tools{display:flex;gap:12px;margin:24px 0}.theme-gallery-tools input{flex:1;min-width:0}.theme-gallery-tools input,.theme-gallery-tools select{background:var(--bz-panel);border:1px solid var(--bz-border-strong);border-radius:8px;padding:12px;color:var(--bz-fg);font:inherit}.theme-gallery-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:16px}.theme-preview{padding:8px;background:var(--bz-panel);color:var(--bz-fg);border:1px solid var(--bz-border);border-radius:12px;text-align:left;font:inherit;cursor:pointer}.theme-preview[aria-pressed=true]{outline:2px solid var(--bz-accent);outline-offset:2px}.theme-preview-art{display:flex;position:relative;height:96px;border-radius:7px;overflow:hidden;background:var(--sample-bg)}.theme-preview-art>i{width:20%;border-right:1px solid var(--sample-secondary);opacity:.5}.theme-preview-lines{padding:18px 12px;display:grid;gap:8px;width:52%}.theme-preview-lines b{height:5px;background:var(--sample-accent);border-radius:2px}.theme-preview-lines b:nth-child(2){width:80%;opacity:.5}.theme-preview-lines b:last-child{width:50%;background:var(--sample-secondary)}.theme-preview-orb{position:absolute;width:52px;height:52px;right:12px;bottom:-12px;border:12px solid var(--sample-secondary);border-radius:50%;opacity:.7}.theme-preview-name{display:flex;align-items:center;justify-content:space-between;gap:8px;font-weight:600;margin:12px 4px 4px}.theme-preview-name .material-symbols-outlined{font-size:18px;color:var(--bz-accent)}.theme-preview small{display:block;margin:0 4px 6px;color:var(--bz-fg-mid)}.theme-gallery footer{margin-top:24px}.theme-gallery button:focus-visible{outline:2px solid var(--bz-accent);outline-offset:3px}@media(max-width:500px){.theme-gallery-backdrop{padding:10px}.theme-gallery{padding:16px}.theme-gallery-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.theme-gallery-tools{flex-wrap:wrap}}
</style>
